import{z as B,x as A,o as i,c as p,q as t,j as s,D as r,d as e,s as n,S as o,b as E}from"./chunks/framework.C8m1ZpeB.js";const T=JSON.parse('{"title":"胶与供应商","description":"","frontmatter":{"title":"胶与供应商","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/resist-vendors.md","filePath":"litho/resist-vendors.md","lastUpdated":1791413859000}'),d={name:"litho/resist-vendors.md"};function h(D,a,m,F,C,u){const l=A("Mermaid");return i(),p("div",null,[a[2]||(a[2]=t('<h1 id="胶与供应商" tabindex="-1">胶与供应商 <a class="header-anchor" href="#胶与供应商" aria-label="Permalink to &quot;胶与供应商&quot;">​</a></h1><div class="epigraph"><p>胶是配方、纯化与认证年周期，不是扫描机附赠的化学品。公开舞台上的名字是 JSR、TOK、信越、富士胶片等；份额不要在没有出处的表里发明。</p><footer>—— 对照各厂公开的光刻胶产品线角色，以及成熟制程国产胶的公开供应，不编造市场份额</footer></div><p><a href="/litho/mask-shop-flow">上一课</a>走完掩模厂。缺口是晶圆上的记录介质从哪来：抗蚀剂供应商与掩模 blank 不是同一张采购单。<a href="/litho/china-litho-supply-chain">国产替代</a>已经按波长档位写过短板；本课只钉公开角色名单，不把百分比写进标题。图形化检测设备从下一课起换工具类别，不再点名胶厂。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>同一台浸没机，换一桶未认证的胶，缺陷和窗口可以整层报废。客户资格认证绑定机台照明、BARC、显影和层别，以年计。上一课的掩模厂周期是天；胶的切换周期是资格。缺口是：谁在公开文本里出现在哪一档波长，而不是「国产化率」。</p><p><span class="marginnote">术语翻译：「认证（qualification）」不是试用满意就买，而是按「层 × 机台 × 配方」逐项签核：工艺窗、缺陷率、颗粒、出气、批次一致性都要留档。换其中任何一项，理论上整套要重走——这就是「以年计」的来源。</span></p><p>供应链课写过日系主导 DUV 胶、EUV 胶仍是短板。本课补的是名字与分工：谁做 KrF/ArF CAR，谁做 i 线 DNQ，谁做 EUV 平台胶——以厂商公开产品线为准，不做排名。</p><h3 id="不要把掩模胶和晶圆胶写成一家" tabindex="-1">不要把掩模胶和晶圆胶写成一家 <a class="header-anchor" href="#不要把掩模胶和晶圆胶写成一家" aria-label="Permalink to &quot;不要把掩模胶和晶圆胶写成一家&quot;">​</a></h3><p>掩模电子束胶、晶圆 ArF 胶、EUV 胶，树脂和金属杂质规格不同。信越等既出现在硅片和部分材料叙述里，也出现在胶；TOK、JSR 以光刻胶与相关化学为公开主业。混厂采购会把杂质规格写错。</p><p><span class="marginnote">本课不引用任何「占全球百分之几」的数字。公开角色够用：能供哪一档波长、是否宣称 EUV 平台。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>读产品线，不读传闻份额。i 线 / g 线：DNQ–酚醛，供应商面更宽，国内北京科华、南大光电等公开服务成熟制程。KrF / ArF：化学放大胶，JSR、东京应化（TOK）、信越、富士胶片、住友、杜邦等出现在公开资料中。EUV：同一批国际厂商的平台胶与金属氧化物路线并行研发，认证仍按层、按机台。</p><p>国产替代的方法仍是档位：成熟 KrF 可切，浸没关键层维持已认证进口直到国产跑完窗口。本课不增加新的许可法律意见。</p>',13)),(i(),s(o,null,{default:r(()=>[n(l,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20IL%5B%22i%20%E7%BA%BF%20DNQ%22%5D%20--%3E%20MAT%5B%22%E6%88%90%E7%86%9F%E5%88%B6%E7%A8%8B%E5%85%AC%E5%BC%80%E5%8F%AF%E5%88%87%22%5D%0A%20%20KRF%5B%22KrF%20%2F%20ArF%20CAR%22%5D%20--%3E%20INT%5B%22JSR%20%2F%20TOK%20%2F%20%E4%BF%A1%E8%B6%8A%E7%AD%89%E5%85%AC%E5%BC%80%E4%BA%A7%E5%93%81%E7%BA%BF%22%5D%0A%20%20EUV%5B%22EUV%20%E5%B9%B3%E5%8F%B0%E8%83%B6%22%5D%20--%3E%20QUAL%5B%22%E6%8C%89%E5%B1%82%E8%AE%A4%E8%AF%81%2C%20%E5%8B%BF%E5%86%99%E4%BB%BD%E9%A2%9D%22%5D%0A%20%20CN%5B%22%E5%9B%BD%E5%86%85%E6%88%90%E7%86%9F%E6%A1%A3%E5%85%AC%E5%BC%80%E4%BE%9B%E5%BA%94%22%5D%20--%3E%20MAT%0A"})]),fallback:r(()=>[...a[0]||(a[0]=[e(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=E("h3",{id:"涂显与胶是一对资格",tabindex:"-1"},[e("涂显与胶是一对资格 "),E("a",{class:"header-anchor",href:"#涂显与胶是一对资格","aria-label":'Permalink to "涂显与胶是一对资格"'},"​")],-1)),a[4]||(a[4]=E("p",null,"胶换了，轨道的温度、排气、浸没配套要重认证。供应商合同往往是胶 + 应用工程师 + 缺陷响应，不是一桶溶剂。把胶写成可以在现货市场即插即用，会低估认证。",-1)),a[5]||(a[5]=E("h2",{id:"机制",tabindex:"-1"},[e("机制 "),E("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[6]||(a[6]=E("p",null,[e("杂质与颗粒在先进节点变成随机缺陷。日系厂商的公开优势叙述包括纯化、过滤和包装，而不只是「会写分子式」。浸没胶还要抗水浸出。EUV 还要出气和金属沾污。这些机制在胶化学课已经按物理讲过；本课只强调它们被"),E("strong",null,"哪一类供应商工业"),e("接住。")],-1)),(i(),s(o,null,{default:r(()=>[n(l,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20NEW%5B%22%E6%8D%A2%E4%B8%80%E6%A1%B6%E6%96%B0%E8%83%B6%22%5D%20--%3E%20TOOL%5B%22%E6%B6%82%E6%98%BE%E9%87%8D%E8%AE%A4%E8%AF%81%3A%20%E6%B8%A9%E5%BA%A6%20%2F%20%E6%8E%92%E6%B0%94%20%2F%20%E6%B5%B8%E6%B2%A1%22%5D%0A%20%20NEW%20--%3E%20OPC%5B%22%E7%B4%A7%E5%87%91%E8%83%B6%E6%A0%B8%E9%87%8D%E6%A0%87%E5%AE%9A%20%E2%86%92%20OPC%20%E9%87%8D%E7%AD%BE%22%5D%0A%20%20NEW%20--%3E%20DEF%5B%22%E7%BC%BA%E9%99%B7%E5%9F%BA%E7%BA%BF%E9%87%8D%E6%B5%8B%22%5D%0A%20%20TOOL%20--%3E%20PW%5B%22%E5%B7%A5%E8%89%BA%E7%AA%97%E9%87%8D%E6%B5%8B%22%5D%0A%20%20DEF%20--%3E%20PW%0A%20%20PW%20--%3E%20SIGN%5B%22%E5%B1%82%20%2B%20%E6%9C%BA%E5%8F%B0%E8%B5%84%E6%A0%BC%E7%AD%BE%E5%AD%97%22%5D%0A%20%20OPC%20--%3E%20SIGN%0A%20%20SIGN%20--%3E%20YEAR%5B%22%E5%91%A8%E6%9C%9F%E4%BB%A5%E5%B9%B4%E8%AE%A1%22%5D%0A"})]),fallback:r(()=>[...a[1]||(a[1]=[e(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=t('<p>计算光刻的紧凑胶核按供应商批次校准。换供应商等于换模型族，OPC 要重签。这是采购决定会打进 DTCO 的原因，不是商务花絮。</p><p><span class="marginnote">直觉类比：换胶不像换打印纸，更像给赛车换轮胎品牌——胎要和悬挂、路面、车手脚法一起重新调校。胶与轨道温度、BARC、显影液、OPC 模型是一套调好的整体，单换一件，其余都要重校。</span></p><p><span class="marginnote">富士胶片、默克 / AZ 等也出现在公开光刻材料目录中。名单是「有公开产品线的角色」，不是排行榜，可随厂商改名而更新。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>禁止编造份额、禁止把研究所分辨率写成晶圆厂资格。禁止把 EUV 胶新闻填进 28 nm 浸没胶缺口——档位课已经禁过，本课名单同样禁。下一课的检测设备（KLA 等）会量胶的缺陷和 CD，但不生产胶；工具类别不要和配方工业吞并。</p><p>也不要把 Chiplet 写成可以少用胶：每颗裸片仍要涂。封装用另一类光刻胶/干膜，不在本名单里冒充 ArF。</p><p><span class="marginnote">常见误区：把「实验室做出 8 nm 分辨率」当成「能供货」。新闻分辨率与晶圆厂资格之间隔着纯化、批次一致性、缺陷率与供货保障——研究所的分辨率写在论文里，供应商的资格写在每一层的认证档案里。</span></p><p><span class="marginnote">出处：JSR、TOK、Shin-Etsu、Fujifilm 等公开产品与技术叙述；国产成熟制程胶企业的公开供应。不使用无出处的市场份额表。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>晶圆胶供应商与掩模厂、扫描机是三条采购链。</li><li>公开角色：JSR、TOK、信越、富士胶片等；国内成熟档有公开供应。</li><li>不写份额；认证绑定层与机台。</li><li>换胶等于换 OPC 胶核与涂显资格。</li><li>图形化检测工具下一课。</li><li>出处：各厂公开产品线；不编造百分比。</li></ul>',10))])}const c=B(d,[["render",h]]);export{T as __pageData,c as default};
